export function answer(question: string): number {
  const trimmed = question.trim();

  // Validate basic structure
  if (!trimmed.startsWith("What is ") || !trimmed.endsWith("?")) {
    throw new Error("Unknown operation");
  }

  const expression = trimmed.slice(8, -1).trim();
  if (!expression) {
    throw new Error("Unknown operation");
  }

  // Normalize the expression: replace "multiplied by" and "divided by" with single tokens
  // We need to be careful with case sensitivity. The examples use lowercase.

  let normalized = expression;

  // Handle "multiplied by"
  const multipliedByIndex = normalized.toLowerCase().indexOf("multiplied by");
  if (multipliedByIndex !== -1) {
    normalized = normalized.substring(0, multipliedByIndex) + "* " + normalized.substring(multipliedByIndex + "multiplied by".length);
  }

  // Handle "divided by"
  const dividedByIndex = normalized.toLowerCase().indexOf("divided by");
  if (dividedByIndex !== -1) {
    normalized = normalized.substring(0, dividedByIndex) + "/ " + normalized.substring(dividedByIndex + "divided by".length);
  }

  // Now split by spaces
  const parts = normalized.split(/\s+/);

  // Parse tokens
  const tokens: (number | string)[] = [];
  for (const part of parts) {
    if (part === "+") {
      tokens.push("+");
    } else if (part === "-") {
      tokens.push("-");
    } else if (part === "*") {
      tokens.push("*");
    } else if (part === "/") {
      tokens.push("/");
    } else {
      // It must be a number
      const num = parseInt(part, 10);
      if (isNaN(num)) {
        throw new Error("Unknown operation");
      }
      tokens.push(num);
    }
  }

  // Evaluate left-to-right
  if (tokens.length === 0) {
    throw new Error("Unknown operation");
  }

  let result = tokens[0];

  for (let i = 1; i < tokens.length; i += 2) {
    const op = tokens[i];
    const nextNum = tokens[i + 1];

    if (typeof nextNum !== "number") {
      throw new Error("Unknown operation");
    }

    if (op === "+") {
      result += nextNum;
    } else if (op === "-") {
      result -= nextNum;
    } else if (op === "*") {
      result *= nextNum;
    } else if (op === "/") {
